import type { DragEvent } from 'react';

export type TaskStatus = 'todo' | 'in_progress' | 'done';

export type PriorityLevel = 'low' | 'medium' | 'high';

export interface KanbanTask {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  priority: PriorityLevel;
  assignee: string;
  dueDate: string;
}

export type TaskFormValues = Omit<KanbanTask, 'id'>;

export interface TaskCardProps {
  task: KanbanTask;
  onDragStart?: (e: DragEvent<HTMLDivElement>, id: string) => void;
  onDragEnd?: () => void;
  onEdit?: (task: KanbanTask) => void;
  onDelete?: (id: string) => void;
  onMove?: (id: string, newStatus: TaskStatus) => void;
}

export interface KanbanColumnProps {
  status: TaskStatus;
  title: string;
  count?: number;
  tasks?: KanbanTask[];
  isDragOver?: boolean;
  onDragOver?: (e: DragEvent<HTMLDivElement>) => void;
  onDragLeave?: (e: DragEvent<HTMLDivElement>) => void;
  onDrop?: (e: DragEvent<HTMLDivElement>, status: TaskStatus) => void;
  onDragStartCard?: (e: DragEvent<HTMLDivElement>, id: string) => void;
  onDragEndCard?: () => void;
  onEditCard?: (task: KanbanTask) => void;
  onDeleteCard?: (id: string) => void;
  onMoveCard?: (id: string, newStatus: TaskStatus) => void;
  onAddTask?: (status: TaskStatus) => void;
}

export interface TaskModalProps {
  isOpen: boolean;
  initialData: KanbanTask | null;
  defaultStatus: TaskStatus;
  onClose?: () => void;
  onSave?: (taskData: TaskFormValues) => void;
}

import { useState } from 'react';
import type { DragEvent, ChangeEvent, MouseEvent } from 'react';
import type { TaskCardProps, TaskStatus } from '../types';

export default function TaskCard({
  task,
  onDragStart,
  onDragEnd,
  onEdit,
  onDelete,
  onMove
}: TaskCardProps) {
  const [isDragging, setIsDragging] = useState<boolean>(false);

  const handleDragStart = (e: DragEvent<HTMLDivElement>) => {
    setIsDragging(true);
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', task.id);
    onDragStart?.(e, task.id);
  };

  const handleDragEnd = () => {
    setIsDragging(false);
    onDragEnd?.();
  };

  const handleStatusChange = (e: ChangeEvent<HTMLSelectElement>) => {
    const nextStatus = e.target.value as TaskStatus;
    if (nextStatus && nextStatus !== task.status) {
      onMove?.(task.id, nextStatus);
    }
  };

  const handleEditClick = (e: MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    onEdit?.(task);
  };

  const handleDeleteClick = (e: MouseEvent<HTMLButtonElement>) => {
    e.stopPropagation();
    const confirmed = window.confirm(`タスク「${task.title}」を削除してもよろしいですか？`);
    if (confirmed) {
      onDelete?.(task.id);
    }
  };

  const getPriorityClass = () => {
    if (task.priority === 'high') return 'task-priority-indicator priority-high';
    if (task.priority === 'medium') return 'task-priority-indicator priority-medium';
    return 'task-priority-indicator priority-low';
  };

  const getPriorityLabel = () => {
    if (task.priority === 'high') return '高';
    if (task.priority === 'medium') return '中';
    return '低';
  };

  const isOverdue = (): boolean => {
    if (!task.dueDate || task.status === 'done') return false;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const dueDate = new Date(task.dueDate);
    dueDate.setHours(0, 0, 0, 0);
    return dueDate < today;
  };

  return (
    <div
      className={`task-card ${isDragging ? 'task-card-dragging' : ''}`}
      draggable
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
    >
      <div className={getPriorityClass()} title={`優先度: ${getPriorityLabel()}`}>
        {getPriorityLabel()}
      </div>

      <div className="task-header">
        <h4 className="task-title">{task.title}</h4>
        <div className="task-actions">
          <button
            type="button"
            className="btn-icon"
            onClick={handleEditClick}
            title="タスクを編集"
            aria-label="編集"
          >
            ✏️
          </button>
          <button
            type="button"
            className="btn-icon"
            onClick={handleDeleteClick}
            title="タスクを削除"
            aria-label="削除"
          >
            🗑️
          </button>
        </div>
      </div>

      {task.description && (
        <p className="task-description">{task.description}</p>
      )}

      <div className="task-meta">
        {task.assignee && (
          <span className="task-assignee" title={`担当者: ${task.assignee}`}>
            👤 {task.assignee}
          </span>
        )}
        {task.dueDate && (
          <span
            className={`task-due ${isOverdue() ? 'is-overdue' : ''}`}
            title={isOverdue() ? `期限切れ: ${task.dueDate}` : `期限: ${task.dueDate}`}
          >
            {isOverdue() ? '⚠️' : '📅'} {task.dueDate}
          </span>
        )}
      </div>

      <select
        className="mobile-move-select"
        value={task.status}
        onChange={handleStatusChange}
        aria-label="状態を変更"
      >
        <option value="todo">移動: 未着手</option>
        <option value="in_progress">移動: 作業中</option>
        <option value="done">移動: 完了</option>
      </select>
    </div>
  );
}

import { useState } from 'react';
import type { DragEvent } from 'react';
import type { KanbanColumnProps } from '../types';
import TaskCard from './TaskCard';

export default function KanbanColumn({
  status,
  title,
  count,
  tasks = [],
  isDragOver = false,
  onDragOver,
  onDragLeave,
  onDrop,
  onDragStartCard,
  onDragEndCard,
  onEditCard,
  onDeleteCard,
  onMoveCard,
  onAddTask
}: KanbanColumnProps) {
  const [dragCounter, setDragCounter] = useState<number>(0);

  const handleDragEnter = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setDragCounter((prev) => prev + 1);
  };

  const handleDragOver = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    onDragOver?.(e);
  };

  const handleDragLeave = (e: DragEvent<HTMLDivElement>) => {
    setDragCounter((prev) => {
      const next = Math.max(0, prev - 1);
      if (next === 0) {
        onDragLeave?.(e);
      }
      return next;
    });
  };

  const handleDrop = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setDragCounter(0);
    onDrop?.(e, status);
  };

  const displayCount = tasks ? tasks.length : (count ?? 0);
  const isOver = isDragOver || dragCounter > 0;

  return (
    <div
      className={`kanban-column ${isOver ? 'kanban-column-over' : ''}`}
      role="region"
      aria-label={`${title} カラム`}
      onDragEnter={handleDragEnter}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
    >
      <div className="column-header">
        <span className="column-title-badge">
          {title}
          <span className="column-count">{displayCount}</span>
        </span>
        <button
          type="button"
          className="btn column-add-btn"
          onClick={() => onAddTask?.(status)}
          title={`${title}にタスクを追加`}
        >
          ＋ 追加
        </button>
      </div>

      <div className="task-list">
        {tasks.length === 0 ? (
          <div className="empty-column-placeholder">
            タスクはありません
          </div>
        ) : (
          tasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              onDragStart={onDragStartCard}
              onDragEnd={onDragEndCard}
              onEdit={onEditCard}
              onDelete={onDeleteCard}
              onMove={onMoveCard}
            />
          ))
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import type { ChangeEvent, FormEvent } from 'react';
import type { TaskModalProps, TaskFormValues } from '../types';

export default function TaskModal({
  isOpen,
  initialData,
  defaultStatus,
  onClose,
  onSave
}: TaskModalProps) {
  const [formData, setFormData] = useState<TaskFormValues>({
    title: '',
    description: '',
    status: defaultStatus,
    priority: 'medium',
    assignee: '',
    dueDate: ''
  });
  const [titleError, setTitleError] = useState<string>('');

  useEffect(() => {
    if (initialData) {
      setFormData({
        title: initialData.title,
        description: initialData.description,
        status: initialData.status,
        priority: initialData.priority,
        assignee: initialData.assignee,
        dueDate: initialData.dueDate
      });
    } else {
      setFormData({
        title: '',
        description: '',
        status: defaultStatus,
        priority: 'medium',
        assignee: '',
        dueDate: ''
      });
    }
    setTitleError('');
  }, [initialData, defaultStatus, isOpen]);

  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose?.();
      }
    };

    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    window.addEventListener('keydown', handleKeyDown);

    return () => {
      document.body.style.overflow = originalOverflow;
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const handleChange = (
    e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>
  ) => {
    const { name, value } = e.target;
    if (name === 'title' && titleError) {
      setTitleError('');
    }
    setFormData((prev) => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!formData.title.trim()) {
      setTitleError('タイトルを入力してください');
      return;
    }
    setTitleError('');
    onSave?.(formData);
  };

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal-card" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h3>{initialData ? 'タスクを編集' : '新規タスク作成'}</h3>
          <button
            type="button"
            className="btn-icon"
            onClick={onClose}
            aria-label="閉じる"
          >
            ✕
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="modal-body">
            <div className="form-group">
              <label className="form-label">
                タイトル <span style={{ color: '#ef4444' }}>*</span>
              </label>
              <input
                type="text"
                name="title"
                required
                maxLength={100}
                className="form-input"
                placeholder="タスクのタイトルを入力"
                value={formData.title}
                onChange={handleChange}
                autoFocus
              />
              {titleError && (
                <p style={{ color: '#ef4444', fontSize: '0.875rem', marginTop: '0.25rem' }}>
                  {titleError}
                </p>
              )}
            </div>

            <div className="form-group">
              <label className="form-label">詳細・メモ</label>
              <textarea
                name="description"
                rows={3}
                className="form-textarea"
                placeholder="詳細な要件やメモを入力"
                value={formData.description}
                onChange={handleChange}
              />
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label">ステータス</label>
                <select
                  name="status"
                  className="form-select"
                  value={formData.status}
                  onChange={handleChange}
                >
                  <option value="todo">未着手</option>
                  <option value="in_progress">作業中</option>
                  <option value="done">完了</option>
                </select>
              </div>

              <div className="form-group">
                <label className="form-label">優先度</label>
                <select
                  name="priority"
                  className="form-select"
                  value={formData.priority}
                  onChange={handleChange}
                >
                  <option value="low">低</option>
                  <option value="medium">中</option>
                  <option value="high">高</option>
                </select>
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label">担当者</label>
                <input
                  type="text"
                  name="assignee"
                  className="form-input"
                  placeholder="例: 佐藤"
                  value={formData.assignee}
                  onChange={handleChange}
                />
              </div>

              <div className="form-group">
                <label className="form-label">期日</label>
                <input
                  type="date"
                  name="dueDate"
                  className="form-input"
                  value={formData.dueDate}
                  onChange={handleChange}
                />
              </div>
            </div>
          </div>

          <div className="modal-footer">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={onClose}
            >
              キャンセル
            </button>
            <button
              type="submit"
              className="btn btn-primary"
            >
              {initialData ? '更新する' : '作成する'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
